# Runstory installer for Windows.
#   powershell -ExecutionPolicy Bypass -c "irm https://runstory.specstory.com/install.ps1 | iex"
# Generated by release/render-installer.mjs from release/install.ps1.in and the
# shared CLI contract. Edit the template, never the rendered file.
#
# It runs in Windows PowerShell 5.1 with .NET Framework 4.7.2 and in PowerShell
# 7, on Windows 10 version 1809 or Windows Server 2019 and later, through 1 code
# path. It checks the signed Windows checksum set and the zip's SHA-256 before
# anything runs, and it installs runstory.exe for the machine's own processor
# with no administrator rights. Every download is curl.exe, which asks no
# question. The script is ASCII, its whole body is 1 function and the last line
# calls it, so a cut download runs nothing. It throws and never calls exit, so
# irm | iex never closes the window. Each refusal prints 1 sentence in red.
function Install-Runstory {
  # Each refusal below throws 1 sentence that starts with "Runstory: ".
  # PowerShell prints a thrown error inside a block of its own, which quotes
  # the line of the script that threw it. So this trap prints the sentence
  # alone in red, and then throws a short error, which keeps the exit code at
  # 1. Any other error keeps its block, because a person needs its line to
  # report it.
  trap {
    $message = [string]$_.Exception.Message
    if (-not $message.StartsWith('Runstory: ')) { break }
    Write-Host $message -ForegroundColor Red
    throw 'Runstory: The install stopped for the reason above.'
  }
  # ConstrainedLanguage mode, e.g. under AppLocker, allows none of the .NET
  # calls below, so the installer stops before it downloads anything and names
  # the steps by hand.
  if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
    Write-Host 'To install by hand:'
    Write-Host '  1. Read the newest version from https://runstory.specstory.com/api/cli/releases/latest.txt.'
    Write-Host '  2. Download runstory_<version>_windows_<arch>.zip from https://runstory.specstory.com/api/cli/releases/v<version>/, and check that its SHA-256 matches its row in runstory_<version>_windows_checksums.txt there.'
    Write-Host '  3. Put runstory.exe from the zip in %USERPROFILE%\.local\bin.'
    throw 'Runstory: This PowerShell runs in ConstrainedLanguage mode, so the installer stopped before it downloaded anything.'
  }
  $ErrorActionPreference = 'Stop'
  $ProgressPreference = 'SilentlyContinue'
  # PowerShell 7.3 and later can turn a native exit code into an error. The
  # installer reads each exit code itself.
  $PSNativeCommandUseErrorActionPreference = $false

  # The build number comes from the registry, which no compatibility shim
  # changes. Windows 10 version 1809 and Windows Server 2019 are build 17763.
  $build = 0
  $version_key = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name CurrentBuildNumber -ErrorAction SilentlyContinue
  if ($null -ne $version_key) { [void][int]::TryParse([string]$version_key.CurrentBuildNumber, [ref]$build) }
  if ($build -lt 17763) { throw 'Runstory: runstory needs Windows 10 version 1809 or later, or Windows Server 2019 or later.' }

  # The machine's processor comes from the registry and never from this
  # process, because an x64 PowerShell on an Arm PC says AMD64.
  $machine = ''
  $environment_key = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment' -Name PROCESSOR_ARCHITECTURE -ErrorAction SilentlyContinue
  if ($null -ne $environment_key) { $machine = [string]$environment_key.PROCESSOR_ARCHITECTURE }
  if ($machine -eq 'AMD64') { $arch = 'amd64' }
  elseif ($machine -eq 'ARM64') { $arch = 'arm64' }
  else { throw 'Runstory: Supported processors are amd64 and arm64.' }

  # TLS 1.2 is added for anything that downloads through .NET, and nothing is
  # turned off. The value 0 lets the system choose, which already holds TLS
  # 1.2 and 1.3, so a list is changed only when it names protocols without 1.2.
  $protocols = [Net.ServicePointManager]::SecurityProtocol
  if ([int]$protocols -ne 0 -and -not ($protocols -band [Net.SecurityProtocolType]::Tls12)) {
    [Net.ServicePointManager]::SecurityProtocol = $protocols -bor [Net.SecurityProtocolType]::Tls12
  }

  # In Windows PowerShell 5.1 the name curl is Invoke-WebRequest, so the full
  # path names the curl.exe that Windows includes.
  $system_root = [Environment]::GetEnvironmentVariable('SystemRoot')
  if ([string]::IsNullOrEmpty($system_root)) { $system_root = 'C:\Windows' }
  $curl = Join-Path $system_root 'System32\curl.exe'
  if (-not (Test-Path -LiteralPath $curl -PathType Leaf)) { throw 'Runstory: This installer needs curl.exe, which Windows 10 version 1809 and later include.' }

  $releases = 'https://runstory.specstory.com/api/cli/releases'
  $storage = 'https://actgnmsszoegjfmjwvry.supabase.co/storage/v1/object/public/cli-releases'
  $version_pattern = '^(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})$'

  # The folder. RUNSTORY_INSTALL_DIR moves it, as on macOS and Linux.
  $dir = [Environment]::GetEnvironmentVariable('RUNSTORY_INSTALL_DIR')
  if ([string]::IsNullOrEmpty($dir)) { $dir = Join-Path ([Environment]::GetFolderPath('UserProfile')) '.local\bin' }
  if ($dir.Contains("`n") -or $dir.Contains("`r")) { throw 'Runstory: The install path cannot contain a newline.' }
  if ($dir -notmatch '^[A-Za-z]:[\\/]' -and $dir -notmatch '^\\\\[^\\]') { throw 'Runstory: RUNSTORY_INSTALL_DIR must be absolute.' }
  $dir = [IO.Path]::GetFullPath($dir)
  if ([IO.Path]::GetPathRoot($dir) -ne $dir) { $dir = $dir.TrimEnd('\') }
  $probe = $dir.ToLowerInvariant() + '\'
  foreach ($managed in @('\microsoft\winget\packages\', '\scoop\apps\', '\chocolatey\lib\', '\node_modules\')) {
    if ($probe.Contains($managed)) { throw 'Runstory: This directory is managed by another installer. Use its update command or choose RUNSTORY_INSTALL_DIR.' }
  }
  # Windows refuses a path of 260 characters or more in more than 1 place,
  # whatever LongPathsEnabled says. The updater checks the version of the
  # staged runstory.exe with this folder as its current directory, which
  # Windows holds under 260 characters, and Windows PowerShell 5.1 refuses a
  # longer file path while LongPathsEnabled is 0. So the installer refuses a
  # folder whose longest path would reach 260 characters, before it makes or
  # downloads anything. The longest name that the install or a later update
  # writes in the folder is the write check below, of 54 characters. The
  # longest names of internal/selfupdate are the stage file
  # .runstory-stage-<32 hex digits>, of 48, and the old copy
  # .runstory-old-<pid>-<16 hex digits>.exe, of at most 45.
  # release/install-ps1.test.mjs holds the bound to those names. The folder
  # is measured as given, which is its long form unless RUNSTORY_INSTALL_DIR
  # names it with 8.3 short names.
  $longest_name = 54
  $longest_folder = 259 - 1 - $longest_name
  if ($dir.Length -gt $longest_folder) { throw "Runstory: The install folder has $($dir.Length) characters, so a path in it would reach the Windows limit of 260 characters. Set RUNSTORY_INSTALL_DIR to a folder of at most $longest_folder characters." }
  try {
    [void][IO.Directory]::CreateDirectory($dir)
    $write_check = Join-Path $dir ('.runstory-write-check-' + [Guid]::NewGuid().ToString('N'))
    [IO.File]::WriteAllBytes($write_check, [byte[]]@())
    [IO.File]::Delete($write_check)
  } catch {
    throw 'Runstory: The install directory must be owned and writable by you. No administrator rights are used.'
  }
  $target = Join-Path $dir 'runstory.exe'

  function Test-Target {
    if (Test-Path -LiteralPath $target) {
      $item = Get-Item -LiteralPath $target -Force
      if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Runstory: Refusing a link or a directory at $target. Use your package manager to update." }
    }
  }

  function Get-Sha256([string]$Path) {
    $sha = [Security.Cryptography.SHA256]::Create()
    $stream = [IO.File]::OpenRead($Path)
    try { $hash = $sha.ComputeHash($stream) } finally { $stream.Dispose(); $sha.Dispose() }
    return ([BitConverter]::ToString($hash) -replace '-', '').ToLowerInvariant()
  }

  # Test-UserPath says whether the user Path of the registry names the folder.
  # Each entry is read raw, then compared with its variables expanded, case
  # folded and with no trailing backslash, the way runstory __install compares
  # it before it adds the folder.
  function Test-UserPath([string]$Folder) {
    $key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Environment')
    if ($null -eq $key) { return $false }
    try { $raw = [string]$key.GetValue('Path', '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames) } finally { $key.Close() }
    $want = $Folder.TrimEnd('\')
    foreach ($entry in $raw.Split(';')) {
      if ([string]::IsNullOrWhiteSpace($entry)) { continue }
      $have = [Environment]::ExpandEnvironmentVariables($entry.Trim()).TrimEnd('\')
      if ([string]::Equals($have, $want, [StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
  }

  # ConvertFrom-DerSignature turns the DER signature the feed carries into the
  # 64 bytes of r and s that .NET Framework's ECDsa reads. It gives $null for
  # anything that is not 1 DER sequence of 2 integers of at most 32 bytes.
  function ConvertFrom-DerSignature([byte[]]$Der) {
    if ($Der.Length -lt 8 -or $Der.Length -gt 72 -or $Der[0] -ne 0x30 -or $Der[1] -ne ($Der.Length - 2)) { return $null }
    $raw = New-Object byte[] 64
    $at = 2
    foreach ($half in 0, 1) {
      if ($at + 2 -gt $Der.Length -or $Der[$at] -ne 0x02) { return $null }
      $length = [int]$Der[$at + 1]
      $at += 2
      if ($length -lt 1 -or $length -gt 33 -or $at + $length -gt $Der.Length) { return $null }
      $skip = 0
      while ($skip -lt $length - 1 -and $Der[$at + $skip] -eq 0) { $skip++ }
      $digits = $length - $skip
      if ($digits -gt 32) { return $null }
      [Array]::Copy($Der, $at + $skip, $raw, 32 * $half + 32 - $digits, $digits)
      $at += $length
    }
    if ($at -ne $Der.Length) { return $null }
    return ,$raw
  }

  # New-ReleaseKey makes the P-256 key from the base64 of its X and Y, because
  # .NET Framework reads no PEM key. It gives $null for anything else. Each
  # point is built apart and then copied in, because a structure that sits
  # inside another one is changed only through a copy in PowerShell.
  function New-ReleaseKey([string]$X, [string]$Y) {
    try {
      $x_bytes = [Convert]::FromBase64String($X)
      $y_bytes = [Convert]::FromBase64String($Y)
      if ($x_bytes.Length -ne 32 -or $y_bytes.Length -ne 32) { return $null }
      $point = New-Object System.Security.Cryptography.ECPoint
      $point.X = $x_bytes
      $point.Y = $y_bytes
      $parameters = New-Object System.Security.Cryptography.ECParameters
      $parameters.Curve = [System.Security.Cryptography.ECCurve+NamedCurves]::nistP256
      $parameters.Q = $point
      return [System.Security.Cryptography.ECDsa]::Create($parameters)
    } catch {
      return $null
    }
  }

  # Read-WindowsSet reads the signed Windows set, which is exactly the 2 zips
  # and the manifest. Each row is 64 lowercase hex digits, 2 spaces and a name,
  # and the set ends with LF. It gives each name's hash.
  function Read-WindowsSet([byte[]]$Set, [string[]]$Wanted) {
    $rows = @{}
    if ($Set.Length -eq 0 -or $Set[$Set.Length - 1] -ne 10) { throw 'Runstory: The signed checksum set is malformed or incomplete.' }
    $text = [Text.Encoding]::ASCII.GetString($Set, 0, $Set.Length - 1)
    foreach ($line in $text.Split("`n")) {
      if ($line -cnotmatch '^([0-9a-f]{64})  ([A-Za-z0-9_.-]+)$') { throw 'Runstory: The signed checksum set is malformed or incomplete.' }
      $hash = $Matches[1]
      $name = $Matches[2]
      if ($Wanted -cnotcontains $name -or $rows.ContainsKey($name)) { throw 'Runstory: The signed checksum set is malformed or incomplete.' }
      $rows[$name] = $hash
    }
    if ($rows.Count -ne $Wanted.Count) { throw 'Runstory: The signed checksum set is malformed or incomplete.' }
    return $rows
  }

  # Expand-Runstory opens the zip through .NET, because the default Restricted
  # policy blocks the script module that holds Expand-Archive. It keeps the
  # rules of install.sh and of the updater: each member is a regular file with
  # a plain name and no folder, appears once in any case, and stays within the
  # size limits, and exactly 1 member is runstory.exe. Only runstory.exe is
  # extracted, and the copy counts its own bytes. It must start as a Windows
  # executable does.
  function Expand-Runstory([string]$Zip, [string]$Candidate) {
    Add-Type -AssemblyName System.IO.Compression
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $archive = $null
    try {
      try { $archive = [IO.Compression.ZipFile]::OpenRead($Zip) } catch { throw 'Runstory: Malformed or oversized compressed archive.' }
      $total = [long]0
      $seen = @{}
      $member = $null
      foreach ($entry in @($archive.Entries)) {
        $name = $entry.FullName
        $file_type = ($entry.ExternalAttributes -shr 16) -band 0xF000
        if ($name -cnotmatch '^[A-Za-z0-9_.-]+$' -or $name -eq '.' -or $name -eq '..' -or $seen.ContainsKey($name) -or ($file_type -ne 0 -and $file_type -ne 0x8000)) { throw 'Runstory: Unsafe or duplicate archive member.' }
        $seen[$name] = $true
        $total += $entry.Length
        if ($entry.Length -gt 104857600 -or $total -gt 268435456) { throw 'Runstory: The expanded archive is too large.' }
        if ($name -ceq 'runstory.exe') { $member = $entry }
      }
      if ($null -eq $member) { throw 'Runstory: Unsafe or duplicate archive member.' }
      $source = $member.Open()
      try {
        $sink = [IO.File]::Open($Candidate, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
        try {
          $buffer = New-Object byte[] 65536
          $written = [long]0
          while (($read = $source.Read($buffer, 0, $buffer.Length)) -gt 0) {
            $written += $read
            if ($written -gt 104857600 -or $written -gt 268435456) { throw 'Runstory: The expanded archive is too large.' }
            $sink.Write($buffer, 0, $read)
          }
        } finally {
          $sink.Dispose()
        }
      } finally {
        $source.Dispose()
      }
    } finally {
      if ($null -ne $archive) { $archive.Dispose() }
    }
    $head = New-Object byte[] 2
    $stream = [IO.File]::OpenRead($Candidate)
    try { $length = $stream.Length; $count = $stream.Read($head, 0, 2) } finally { $stream.Dispose() }
    if ($length -lt 2 -or $length -gt 104857600 -or $count -ne 2 -or $head[0] -ne 0x4D -or $head[1] -ne 0x5A) { throw 'Runstory: Invalid packaged binary.' }
  }

  # The feed's public key, which the renderer writes. No key ever comes from
  # the feed.
  $keyX = 'bv6sY0W8/yYrF7RnAfSta3LHTY2q8K7pPn70/RZNmFk='
  $keyY = 'z5gTamr9aeRD1HYXv7U1XXCk42kFbHYp+yumd8EZ6Vk='
  $ecdsa = New-ReleaseKey $keyX $keyY
  if ($null -eq $ecdsa) { throw 'Runstory: Release signing is not configured yet. No binary was replaced.' }

  Test-Target
  $before = 'absent'
  if (Test-Path -LiteralPath $target -PathType Leaf) { $before = Get-Sha256 $target }

  $work = Join-Path ([IO.Path]::GetTempPath()) ('runstory-install-' + [Guid]::NewGuid().ToString('N'))
  [void][IO.Directory]::CreateDirectory($work)
  # A network that blocks the certificate revocation check makes curl.exe fail
  # with 0x80092012 or 0x80092013. The download then runs once more with
  # --ssl-revoke-best-effort, which still refuses a certificate known to be
  # revoked, and every later download keeps that flag.
  $state = @{ BestEffort = $false }

  # Invoke-Curl downloads 1 URL into the file body of the work folder, with no
  # redirect followed, and gives the HTTP code. curl.exe runs in the work
  # folder with plain file names, so a profile path outside the code page never
  # reaches it. A failed download stops with the sentence of its kind.
  function Invoke-Curl([string]$Url, [long]$Limit, [bool]$Artifact) {
    Push-Location -LiteralPath $work
    try {
      foreach ($attempt in 1, 2) {
        foreach ($name in 'body', 'headers', 'errors') { if (Test-Path -LiteralPath $name) { Remove-Item -LiteralPath $name -Force } }
        $arguments = @('--silent', '--show-error', '--proto', '=https', '--tlsv1.2', '--connect-timeout', '15', '--max-time', '300', '--max-filesize', [string]$Limit, '--max-redirs', '0', '--dump-header', 'headers', '--stderr', 'errors', '--output', 'body')
        if ($state.BestEffort) { $arguments += '--ssl-revoke-best-effort' }
        & $curl @arguments $Url | Out-Null
        $status = $LASTEXITCODE
        if ($status -eq 0) { break }
        $errors = ''
        if (Test-Path -LiteralPath 'errors') { $errors = [IO.File]::ReadAllText((Join-Path $work 'errors')) }
        if ($attempt -eq 1 -and -not $state.BestEffort -and $errors -match '0x80092012|0x80092013') {
          $state.BestEffort = $true
          Write-Host 'This network blocks the check that the download certificate was not revoked, so the download runs again with a best effort check.'
          continue
        }
        if ($status -eq 63) { throw 'Runstory: A release download exceeded its size limit.' }
        if ($errors.Trim()) { [Console]::Error.WriteLine($errors.Trim()) }
        if ($Artifact) { throw 'Runstory: Artifact download failed.' }
        throw 'Runstory: Download failed. The existing installation was not replaced.'
      }
      $code = ''
      foreach ($line in [IO.File]::ReadAllLines((Join-Path $work 'headers'))) { if ($line -match '^HTTP/\S+\s+([0-9]{3})') { $code = $Matches[1] } }
      $size = 0
      if (Test-Path -LiteralPath 'body') { $size = (Get-Item -LiteralPath 'body').Length }
      if ($size -gt $Limit) { throw 'Runstory: A release download exceeded its size limit.' }
      return $code
    } finally {
      Pop-Location
    }
  }

  # Get-Release fetches 1 release file into Output. The release route may
  # redirect once, and only to the exact public object at the pinned storage
  # origin. With MayBeMissing, a route or a storage that answers that the file
  # does not exist gives $false, and every other failure stops.
  function Get-Release([string]$Url, [string]$Output, [long]$Limit, [string]$Expected, [switch]$MayBeMissing) {
    $code = Invoke-Curl $Url $Limit $false
    if ($code -in @('302', '307', '308')) {
      $location = ''
      foreach ($line in [IO.File]::ReadAllLines((Join-Path $work 'headers'))) { if ($line -match '^location:\s*(.*)$') { $location = $Matches[1].Trim() } }
      if (-not $Expected -or $location -cne $Expected) { throw 'Runstory: The release redirected to an unexpected location.' }
      $code = Invoke-Curl $location $Limit $true
      if ($code -ne '200') {
        if ($MayBeMissing -and $code -in @('400', '404')) { return $false }
        throw 'Runstory: Artifact storage did not return the requested file.'
      }
    } elseif ($code -ne '200') {
      if ($MayBeMissing -and $code -eq '404') { return $false }
      throw "Runstory: Release download returned HTTP $code."
    }
    $body = Join-Path $work 'body'
    if (-not (Test-Path -LiteralPath $body)) { [IO.File]::WriteAllBytes($body, [byte[]]@()) }
    if (Test-Path -LiteralPath $Output) { Remove-Item -LiteralPath $Output -Force }
    [IO.File]::Move($body, $Output)
    return $true
  }

  try {
    $from_pointer = $false
    $version = [Environment]::GetEnvironmentVariable('RUNSTORY_VERSION')
    if ([string]::IsNullOrEmpty($version)) {
      $from_pointer = $true
      $pointer = Join-Path $work 'latest'
      [void](Get-Release "$releases/latest.txt" $pointer 32 '')
      $bytes = [IO.File]::ReadAllBytes($pointer)
      if ($bytes.Length -lt 2 -or $bytes[$bytes.Length - 1] -ne 10) { throw 'Runstory: The release pointer is malformed.' }
      $version = [Text.Encoding]::ASCII.GetString($bytes, 0, $bytes.Length - 1)
      if ($version.Contains("`n") -or $version.Contains("`r")) { throw 'Runstory: The release pointer is malformed.' }
    }
    if ($version.Contains("`n") -or $version.Contains("`r") -or $version -cnotmatch $version_pattern) { throw 'Runstory: Expected a stable version such as 1.2.3.' }

    $platform = "windows_$arch"
    $archive = 'runstory_{version}_{platform}.zip'.Replace('{version}', $version).Replace('{platform}', $platform)
    $archives = @('windows_amd64 windows_arm64'.Split(' ') | ForEach-Object { 'runstory_{version}_{platform}.zip'.Replace('{version}', $version).Replace('{platform}', $_) })
    $checksums = 'runstory_{version}_windows_checksums.txt'.Replace('{version}', $version)
    $signature = 'runstory_{version}_windows_checksums.txt.sig'.Replace('{version}', $version)
    $manifest = 'runstory_{version}_release.json'.Replace('{version}', $version)
    $base = "$releases/v$version"
    $object = "$storage/v$version"

    Write-Host "Runstory $version"
    Write-Host "  1/3 Downloading and checking the signature for windows/$arch..."
    $checksums_file = Join-Path $work 'checksums'
    $signature_file = Join-Path $work 'signature'
    $found = Get-Release "$base/$checksums" $checksums_file 4096 "$object/$checksums" -MayBeMissing
    if (-not $found) {
      if ($from_pointer) { throw "Runstory: The newest version of runstory, $version, has no Windows build yet." }
      throw "Runstory: Runstory $version has no Windows build."
    }
    [void](Get-Release "$base/$signature" $signature_file 128 "$object/$signature")
    $set = [IO.File]::ReadAllBytes($checksums_file)
    $raw = ConvertFrom-DerSignature ([IO.File]::ReadAllBytes($signature_file))
    if ($null -eq $raw -or -not $ecdsa.VerifyData($set, $raw, [Security.Cryptography.HashAlgorithmName]::SHA256)) { throw 'Runstory: Release signature verification failed. Nothing was installed.' }

    $rows = Read-WindowsSet $set (@($archives) + @($manifest))

    $zip_file = Join-Path $work 'archive.zip'
    $manifest_file = Join-Path $work 'manifest'
    [void](Get-Release "$base/$archive" $zip_file 104857600 "$object/$archive")
    [void](Get-Release "$base/$manifest" $manifest_file 4096 "$object/$manifest")
    if ((Get-Sha256 $zip_file) -cne $rows[$archive] -or (Get-Sha256 $manifest_file) -cne $rows[$manifest]) { throw 'Runstory: A release file failed its SHA-256 check.' }

    Write-Host '  2/3 Checking the packaged executable...'
    $candidate = Join-Path $work 'runstory.exe'
    Expand-Runstory $zip_file $candidate
    $binary_hash = Get-Sha256 $candidate

    Test-Target
    $now = 'absent'
    if (Test-Path -LiteralPath $target -PathType Leaf) { $now = Get-Sha256 $target }
    if ($now -cne $before) { throw 'Runstory: The installation changed during download. Run the installer again.' }

    # runstory __install checks its own hash and version, takes the install
    # lock, checks that you own the folder, replaces runstory.exe safely, writes
    # the receipt and adds the folder to the user Path once.
    Write-Host '  3/3 Installing...'
    $no_modify = [Environment]::GetEnvironmentVariable('RUNSTORY_NO_MODIFY_PATH') -eq '1'
    $on_path_before = Test-UserPath $dir
    $saved_check = [Environment]::GetEnvironmentVariable('RUNSTORY_NO_UPDATE_CHECK', 'Process')
    [Environment]::SetEnvironmentVariable('RUNSTORY_NO_UPDATE_CHECK', '1', 'Process')
    # Its refusal goes to standard error, which Windows PowerShell 5.1 may turn
    # into an error record, so the exit code decides and not that record.
    $ErrorActionPreference = 'Continue'
    try {
      & $candidate __install --dir $dir --version $version --sha256 $binary_hash
      $install_status = $LASTEXITCODE
    } finally {
      $ErrorActionPreference = 'Stop'
      [Environment]::SetEnvironmentVariable('RUNSTORY_NO_UPDATE_CHECK', $saved_check, 'Process')
    }
    if ($install_status -ne 0) { throw 'Runstory: Native installation failed. Follow its recovery instructions above.' }
    if (-not (Test-Path -LiteralPath $target -PathType Leaf) -or (Get-Sha256 $target) -cne $binary_hash) { throw 'Runstory: The installed binary did not match the verified candidate.' }

    Write-Host ''
    Write-Host "Installed and verified: $version"
    Write-Host "Location: $target"
    foreach ($other in @(Get-Command -Name 'runstory' -CommandType Application -All -ErrorAction SilentlyContinue)) {
      if ($other.Path -and -not [string]::Equals($other.Path, $target, [StringComparison]::OrdinalIgnoreCase)) { Write-Host "Other installation left in place: $($other.Path)" }
    }
    if ($no_modify) {
      Write-Host "Your user Path is as it was, because RUNSTORY_NO_MODIFY_PATH is 1. Add $dir to it, or run runstory by its full path."
      Write-Host ''
      Write-Host 'Then set up your project:'
    } else {
      if ($on_path_before) { Write-Host "$dir is on your user Path already." }
      elseif (Test-UserPath $dir) { Write-Host "Added $dir to your user Path." }
      else { Write-Host "Your user Path does not hold $dir yet. Add it, or run runstory by its full path." }
      Write-Host ''
      Write-Host 'Open a new terminal, then set up your project:'
    }
    Write-Host '  runstory init'
    Write-Host '  runstory setup'
  } finally {
    $ecdsa.Dispose()
    if (Test-Path -LiteralPath $work) { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
  }
}
# Keep this call last. A truncated script cannot run a partial installer.
Install-Runstory
